// ===== Error Alert (Free) v1.0 =====
// Set this workflow as the Error Workflow of the workflows you want to watch
// (Workflow settings > Error Workflow). It runs whenever one of them fails,
// including failures raised by Silent Data Failure Guard.
// Open the "Send Email" node and set your SMTP credential and recipient.

const GUARD_PREFIX = '[Silent Data Failure Guard]';

const data = $input.first().json;
const execution = data.execution || {};
const workflow = data.workflow || {};
const message = (execution.error && execution.error.message) || 'Unknown error';
const isGuardError = message.includes(GUARD_PREFIX);

const kind = isGuardError ? 'Silent data failure' : 'Workflow error';
const subject = `${kind}: ${workflow.name || 'Unknown workflow'}`;
const text = [
  subject,
  `Node: ${execution.lastNodeExecuted || 'unknown'}`,
  `Message: ${message}`,
  execution.url ? `Execution: ${execution.url}` : `Execution ID: ${execution.id || 'unknown'}`,
  `Time: ${new Date().toISOString()}`,
].join('\n');

return [{ json: { isGuardError, subject, text } }];
